1	//! Rust port of `tests/test7.cpp` from earcut.hpp: triangulate a two-turn spiral
2	//! sampled at `2 * n` points and print the resulting triangle indices.
3	//!
4	//! Usage: `test7 [n]` — `n` defaults to 7 and is parsed with `atoi` semantics.
5	
6	// `#[path]` module declarations keep this file buildable both standalone
7	// (`rustc test7.rs`) and as the Cargo `[[bin]]` target at the package root.
8	#[path = "src/cli.rs"]
9	mod cli;
10	#[path = "src/earcut/mod.rs"]
11	mod earcut;
12	#[path = "src/spiral.rs"]
13	mod spiral;
14	
15	use std::io::Write;
16	
17	fn main() {
18	    let args: Vec<String> = std::env::args().collect();
19	
20	    let mut n: i32 = 7;
21	    if args.len() > 1 {
22	        n = cli::atoi(&args[1]);
23	    }
24	
25	    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
26	    let spiral = spiral::spiral(n);
27	
28	    polygon.push(spiral);
29	
30	    let indices = earcut::earcut(&polygon);
31	
32	    // `std::cout << idx << " "` for each index: no separator logic, no trailing
33	    // newline.
34	    let mut out = String::new();
35	    for idx in &indices {
36	        out.push_str(&idx.to_string());
37	        out.push(' ');
38	    }
39	
40	    let stdout = std::io::stdout();
41	    let mut handle = stdout.lock();
42	    // A failed write leaves `std::cout` in a bad state but still returns 0 from
43	    // main, so swallow errors rather than panicking (Rust ignores SIGPIPE, which
44	    // would otherwise turn a truncated pipe into a panic message on stderr).
45	    let _ = handle.write_all(out.as_bytes());
46	    let _ = handle.flush();
47	}
48

1	#include <iostream>
2	#include <vector>
3	#include <array>
4	#include "../earcut.hpp"
5	
6	int main(int argc, char* argv[]) {
7	    int n = 7;
8	    if (argc > 1) {
9	        n = std::atoi(argv[1]);
10	    }
11	    
12	    std::vector<std::vector<std::array<double, 2>>> polygon;
13	    std::vector<std::array<double, 2>> spiral;
14	    
15	    for (int i = 0; i < n * 2; i++) {
16	        double t = double(i) / (n * 2);
17	        double radius = t;
18	        double angle = 4.0 * M_PI * t;
19	        spiral.push_back({radius * std::cos(angle), radius * std::sin(angle)});
20	    }
21	    
22	    polygon.push_back(spiral);
23	    
24	    auto indices = mapbox::earcut<uint32_t>(polygon);
25	    
26	    for (auto idx : indices) {
27	        std::cout << idx << " ";
28	    }
29	    return 0;
30	}
